  const instanceId = envVars.INSTANCE_ID || import_os.default.hostname();
  const instanceType = envVars.INSTANCE_TYPE || "t3.medium";
  const projectName = envVars.APP_NAME || (() => {
    try {
      return require(import_path.default.join(cwd, "package.json")).name;
    } catch {
      return import_path.default.basename(cwd);
    }
  })();
  console.log(import_picocolors.default.green(`\u2705 ${provider.toUpperCase()} / ${region}`));
