  console.log(import_picocolors.default.green("  \u2502") + import_picocolors.default.bold("  \u{1F33F} CarboniX initialized successfully!              ") + import_picocolors.default.green("\u2502"));
  console.log(import_picocolors.default.green("  \u251C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2524"));
  console.log(import_picocolors.default.green("  \u2502") + `  Provider : ${import_picocolors.default.cyan(provider.padEnd(10))} Region : ${import_picocolors.default.cyan(region.padEnd(16))}` + import_picocolors.default.green("  \u2502"));
  console.log(import_picocolors.default.green("  \u2502") + `  Project  : ${import_picocolors.default.white(projectName.substring(0, 37).padEnd(39))}` + import_picocolors.default.green("\u2502"));
  console.log(import_picocolors.default.green("  \u251C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2524"));
