program.command("status").description("Check your CarboniX connection and show live emission stats").action(async () => {
  const config = await readConfig();
  const baseUrl = config.baseUrl || DEFAULT_API_BASE;
  console.log("");
  console.log(import_picocolors.default.cyan("  \u{1F50D} Checking CarboniX connection..."));
  console.log("");
  try {
    process.stdout.write(import_picocolors.default.gray("  API Server... "));
    await import_axios.default.get(`${baseUrl}/api/v1/health`, { timeout: 5e3 });
    console.log(import_picocolors.default.green("\u2705 Online"));
  } catch {
    console.log(import_picocolors.default.red("\u274C Offline"));
    console.error(import_picocolors.default.gray(`  Cannot reach: ${baseUrl}`));
    process.exit(1);
  }
  try {
    process.stdout.write(import_picocolors.default.gray("  API Key...    "));
    const res = await import_axios.default.post(`${baseUrl}/api/v1/carbon/verify-key`, {}, {
      headers: { "Authorization": `Bearer ${config.apiKey}` },
      timeout: 5e3
    });
    if (!res.data.success) throw new Error("invalid");
    console.log(import_picocolors.default.green("\u2705 Valid"));
  } catch {
    console.log(import_picocolors.default.red("\u274C Invalid or expired"));
    console.error(import_picocolors.default.gray("  Get a new key from your Dashboard \u2192 Settings \u2192 API Keys"));
    process.exit(1);
  }
  try {
    process.stdout.write(import_picocolors.default.gray("  Emission data... "));
    const res = await import_axios.default.get(`${baseUrl}/api/v1/carbon/summary`, {
      headers: { "Authorization": `Bearer ${config.apiKey}` },
      timeout: 5e3
    });
    console.log(import_picocolors.default.green("\u2705 Connected"));
    if (res.data?.data) {
      const d = res.data.data;
      console.log("");
      console.log(import_picocolors.default.white(`  Current Month  : ${import_picocolors.default.yellow(d.totalCarbonKg?.toFixed(2) + " kg CO\u2082e")}`));
      console.log(import_picocolors.default.white(`  Instances      : ${import_picocolors.default.cyan(d.instanceCount)}`));
      console.log(import_picocolors.default.white(`  Idle Servers   : ${import_picocolors.default.red(d.idleCount)}`));
      console.log(import_picocolors.default.white(`  Oversized      : ${import_picocolors.default.red(d.oversizedCount)}`));
    }
  } catch {
    console.log(import_picocolors.default.gray("(no data yet \u2014 deploy and run your server to see emissions)"));
  }
  console.log("");
  console.log(import_picocolors.default.gray(`  Project  : ${config.projectName || "unknown"}`));
  console.log(import_picocolors.default.gray(`  Provider : ${config.provider || "unknown"} / ${config.region || "unknown"}`));
  console.log(import_picocolors.default.gray(`  API Base : ${baseUrl}`));
  console.log("");
});
